    /**
     * Gets data_status
     *
     * @return string|null
     */
    public function getDataStatus()
    {
        return $this->container['data_status'];
    }

    /**
     * Sets data_status
     *
     * @param string|null $data_status Data status: 'on-time' if the last observation is within 3 times the transmit interval, 'outdated' otherwise, or 'NA' when no data is available.
     *
     * @return self
     */
    public function setDataStatus($data_status)
    {
        if (is_null($data_status)) {
            throw new \InvalidArgumentException('non-nullable data_status cannot be null');
        }
        $allowedValues = $this->getDataStatusAllowableValues();
        if (!in_array($data_status, $allowedValues, true)) {
            throw new \InvalidArgumentException(
                sprintf(
                    "Invalid value '%s' for 'data_status', must be one of '%s'",
                    $data_status,
                    implode("', '", $allowedValues)
                )
